#include <stdio.h>
#include <math.h>

#define MAX_N 10
#define MAX_M 500
#define MAX_T 100

double prob[MAX_N][MAX_M + 1]; // prob[i][k] = probability runner i rests exactly k times
double time_if_rest[MAX_N][MAX_M + 1]; // finishing time if rests k times
double win_prob[MAX_N];

int main() {
    int N, M;
    double L;
    scanf("%d %d %lf", &N, &M, &L);

    double P[MAX_N], T[MAX_N], V[MAX_N];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf", &P[i], &T[i], &V[i]);
        P[i] /= 100.0; // convert percent to probability
    }

    // Precompute probability distributions and times
    for (int i = 0; i < N; i++) {
        double p = P[i];
        // Binomial probability for exactly k rests
        double coef = 1.0; // C(M,0)
        for (int k = 0; k <= M; k++) {
            prob[i][k] = coef * pow(p, k) * pow(1 - p, M - k);
            time_if_rest[i][k] = L / V[i] + k * T[i];
            // Update binomial coefficient for next k
            coef *= (double)(M - k) / (k + 1);
        }
    }

    // For each runner, compute probability they win
    for (int i = 0; i < N; i++) {
        win_prob[i] = 0.0;
        for (int ki = 0; ki <= M; ki++) {
            double prob_i = prob[i][ki];
            if (prob_i == 0.0) continue;
            double ti = time_if_rest[i][ki];
            double prob_all_slower = 1.0;

            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                double prob_j_slower = 0.0;
                for (int kj = 0; kj <= M; kj++) {
                    double tj = time_if_rest[j][kj];
                    if (tj > ti) {
                        prob_j_slower += prob[j][kj];
                    }
                }
                prob_all_slower *= prob_j_slower;
            }
            win_prob[i] += prob_i * prob_all_slower;
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%.10lf\n", win_prob[i]);
    }

    return 0;
}

