int main() {
    int N, M;
    double L;
    scanf("%d %d %lf", &N, &M, &L);

    double P[105], T[105], V[105];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf", &P[i], &T[i], &V[i]);
        P[i] /= 100.0;
    }

    int total = 1 << M;

    // For each runner, precompute finish time and probability for each subset
    double *times = (double*)malloc(N * total * sizeof(double));
    double *probs = (double*)malloc(N * total * sizeof(double));

    for (int i = 0; i < N; i++) {
        for (int s = 0; s < total; s++) {
            double rest = 0;
            double prob = 1.0;
            for (int k = 0; k < M; k++) {
                if (s & (1 << k)) { rest += T[i]; prob *= P[i]; }
                else { prob *= (1 - P[i]); }
            }
            times[i * total + s] = L / V[i] + rest;
            probs[i * total + s] = prob;
        }
    }

    for (int i = 0; i < N; i++) {
        double win_prob = 0.0;
        for (int si = 0; si < total; si++) {
            double ti = times[i * total + si];
            double pi = probs[i * total + si];
            double others = 1.0;
            for (int j = 0; j < N; j++) {
                if (j == i) continue;
                double pj_slower = 0.0;
                for (int sj = 0; sj < total; sj++) {
                    if (times[j * total + sj] > ti) pj_slower += probs[j * total + sj];
                }
                others *= pj_slower;
            }
            win_prob += pi * others;
        }
        printf("%.6f\n", win_prob);
    }
    free(times); free(probs);
    return 0;
}

