typedef long double ld;

static int cmp_ld(const void *a, const void *b) {
    ld x = *(const ld *)a;
    ld y = *(const ld *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M;
    ld L;
    if (scanf("%d %d %Lf", &N, &M, &L) != 3) return 0;

    ld *P = (ld *)malloc(N * sizeof(ld));
    ld *T = (ld *)malloc(N * sizeof(ld));
    ld *V = (ld *)malloc(N * sizeof(ld));

    for (int i = 0; i < N; ++i) {
        scanf("%Lf %Lf %Lf", &P[i], &T[i], &V[i]);
        P[i] /= 100.0L;
    }

    ld *answer = (ld *)calloc(N, sizeof(ld));

    for (int i = 0; i < N; ++i) {
        /* Distribution of runner i:
           total_time = L / V[i] + k * T[i], k = 0..M
           prob(k) = C(M,k) p^k (1-p)^(M-k)
        */
        ld base_i = L / V[i];

        /* Precompute pmf for runner i */
        ld *pmf_i = (ld *)malloc((M + 1) * sizeof(ld));
        if (fabsl(P[i]) < 1e-18L) {
            pmf_i[0] = 1.0L;
            for (int k = 1; k <= M; ++k) pmf_i[k] = 0.0L;
        } else if (fabsl(P[i] - 1.0L) < 1e-18L) {
            for (int k = 0; k < M; ++k) pmf_i[k] = 0.0L;
            pmf_i[M] = 1.0L;
        } else {
            ld p = P[i], q = 1.0L - p;
            pmf_i[0] = 1.0L;
            for (int t = 0; t < M; ++t) pmf_i[0] *= q;
            for (int k = 0; k < M; ++k) {
                pmf_i[k + 1] = pmf_i[k] * (ld)(M - k) / (ld)(k + 1) * p / q;
            }
        }

        for (int k = 0; k <= M; ++k) {
            if (pmf_i[k] == 0.0L) continue;
            ld time_i = base_i + (ld)k * T[i];
            ld win_prob_given = 1.0L;

            for (int j = 0; j < N; ++j) {
                if (j == i) continue;

                ld base_j = L / V[j];
                ld less_prob = 0.0L;

                /* Compute P(time_j > time_i), since ties do not count as win */
                if (fabsl(P[j]) < 1e-18L) {
                    ld time_j = base_j;
                    if (time_j > time_i) less_prob = 1.0L;
                    else less_prob = 0.0L;
                } else if (fabsl(P[j] - 1.0L) < 1e-18L) {
                    ld time_j = base_j + (ld)M * T[j];
                    if (time_j > time_i) less_prob = 1.0L;
                    else less_prob = 0.0L;
                } else {
                    ld p = P[j], q = 1.0L - p;
                    ld pmf = 1.0L;
                    for (int t = 0; t < M; ++t) pmf *= q;

                    for (int s = 0; s <= M; ++s) {
                        ld time_j = base_j + (ld)s * T[j];
                        if (time_j > time_i) less_prob += pmf;
                        if (s < M) pmf = pmf * (ld)(M - s) / (ld)(s + 1) * p / q;
                    }
                }

                win_prob_given *= less_prob;
                if (win_prob_given == 0.0L) break;
            }

            answer[i] += pmf_i[k] * win_prob_given;
        }

        free(pmf_i);
    }

    for (int i = 0; i < N; ++i) {
        printf("%.10Lf\n", answer[i]);
    }

    free(P);
    free(T);
    free(V);
    free(answer);
    return 0;
}

