int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    double L;
    cin >> N >> M >> L;

    vector<double> P(N), T(N), V(N);
    for (int i = 0; i < N; i++) {
        cin >> P[i] >> T[i] >> V[i];
        P[i] /= 100.0; // convert to probability
    }

    // Precompute binomial probabilities for each runner
    vector<vector<double>> binom(N, vector<double>(M + 1, 0.0));
    for (int i = 0; i < N; i++) {
        double p = P[i];
        // Compute using DP: binom[i][k] = C(M,k) * p^k * (1-p)^(M-k)
        vector<vector<double>> dp(M + 1, vector<double>(M + 1, 0.0));
        dp[0][0] = 1.0;
        for (int place = 1; place <= M; place++) {
            for (int k = 0; k <= place; k++) {
                dp[place][k] = dp[place-1][k] * (1 - p);
                if (k > 0)
                    dp[place][k] += dp[place-1][k-1] * p;
            }
        }
        binom[i] = dp[M];
    }

    // Precompute base running time
    vector<double> runTime(N);
    for (int i = 0; i < N; i++)
        runTime[i] = L / V[i];

    // For each runner, compute win probability
    for (int i = 0; i < N; i++) {
        double winProb = 0.0;
        // For each possible number of breaks for runner i
        for (int ki = 0; ki <= M; ki++) {
            double time_i = runTime[i] + ki * T[i];
            double prob_i = binom[i][ki];
            if (prob_i == 0.0) continue;

            // Probability all others take strictly longer time
            double probAllLonger = 1.0;
            for (int j = 0; j < N; j++) {
                if (j == i) continue;
                double probLonger = 0.0;
                for (int kj = 0; kj <= M; kj++) {
                    double time_j = runTime[j] + kj * T[j];
                    if (time_j > time_i)
                        probLonger += binom[j][kj];
                }
                probAllLonger *= probLonger;
            }
            winProb += prob_i * probAllLonger;
        }
        cout << fixed << setprecision(9) << winProb << "\n";
    }

    return 0;
}

