int main() {
    int N, M;
    double L;
    cin >> N >> M >> L;

    vector<double> P(N), T(N), V(N);
    for (int i = 0; i < N; i++) {
        cin >> P[i] >> T[i] >> V[i];
        P[i] /= 100.0;
    }

    // Precompute binomial probabilities
    // binom[i][k] = P(runner i rests k times)
    vector<vector<double>> binom(N, vector<double>(M+1, 0));
    for (int i = 0; i < N; i++) {
        binom[i][0] = 1.0;
        for (int j = 0; j < M; j++) {
            for (int k = j+1; k >= 1; k--) {
                binom[i][k] = binom[i][k] * (1-P[i]) + binom[i][k-1] * P[i];
            }
            binom[i][0] *= (1-P[i]);
        }
    }

    vector<double> base(N);
    for (int i = 0; i < N; i++) base[i] = L / V[i];

    vector<double> win(N, 0.0);

    // Enumerate all combinations
    vector<int> k(N, 0);
    function<void(int, double)> solve = [&](int idx, double prob) {
        if (idx == N) {
            vector<double> times(N);
            for (int i = 0; i < N; i++) times[i] = base[i] + k[i] * T[i];
            double mn = *min_element(times.begin(), times.end());
            int cnt = count_if(times.begin(), times.end(), [mn](double t){ return t == mn; });
            if (cnt == 1) {
                for (int i = 0; i < N; i++)
                    if (times[i] == mn) win[i] += prob;
            }
            return;
        }
        for (int ki = 0; ki <= M; ki++) {
            k[idx] = ki;
            solve(idx+1, prob * binom[idx][ki]);
        }
    };

    solve(0, 1.0);

    cout << fixed << setprecision(6);
    for (int i = 0; i < N; i++) cout << win[i] << "\n";

    return 0;
}

