int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    double L;
    cin >> N >> M >> L;

    vector<double> P(N), T(N), V(N);
    for (int i = 0; i < N; ++i) {
        cin >> P[i] >> T[i] >> V[i];
        P[i] /= 100.0;
    }

    // For runner i:
    // total time = L / V[i] + k * T[i], where k ~ Binomial(M, P[i])
    // Probability of exactly k rests:
    // C(M,k) * p^k * (1-p)^(M-k)
    //
    // Need probability that runner i has strictly smaller finish time than all others.

    vector<vector<double>> prob(N, vector<double>(M + 1, 0.0));
    vector<vector<double>> times(N, vector<double>(M + 1, 0.0));

    for (int i = 0; i < N; ++i) {
        double p = P[i];
        double q = 1.0 - p;

        // Build binomial distribution stably.
        if (M == 0) {
            prob[i][0] = 1.0;
        } else if (p == 0.0) {
            prob[i][0] = 1.0;
        } else if (p == 1.0) {
            prob[i][M] = 1.0;
        } else {
            prob[i][0] = pow(q, M);
            for (int k = 0; k < M; ++k) {
                prob[i][k + 1] = prob[i][k] * (M - k) / (k + 1) * (p / q);
            }
        }

        double base = L / V[i];
        for (int k = 0; k <= M; ++k) {
            times[i][k] = base + k * T[i];
        }
    }

    vector<double> ans(N, 0.0);

    const double EPS = 1e-12;

    for (int i = 0; i < N; ++i) {
        double win = 0.0;

        for (int ki = 0; ki <= M; ++ki) {
            if (prob[i][ki] == 0.0) continue;

            double ti = times[i][ki];
            double cur = prob[i][ki];

            bool possible = true;
            for (int j = 0; j < N; ++j) {
                if (j == i) continue;

                double s = 0.0;
                for (int kj = 0; kj <= M; ++kj) {
                    if (times[j][kj] > ti + EPS) {
                        s += prob[j][kj];
                    }
                }

                if (s <= 0.0) {
                    possible = false;
                    break;
                }
                cur *= s;
            }

            if (possible) win += cur;
        }

        ans[i] = win;
    }

    cout.setf(ios::fixed);
    cout << setprecision(10);
    for (int i = 0; i < N; ++i) {
        cout << ans[i] << "\n";
    }

    return 0;
}

