public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        double L = sc.nextDouble();

        double[] P = new double[N], T = new double[N], V = new double[N];
        for (int i = 0; i < N; i++) {
            P[i] = sc.nextDouble() / 100.0;
            T[i] = sc.nextDouble();
            V[i] = sc.nextDouble();
        }

        // Precompute binomial coefficients
        double[][] binom = new double[M+1][M+1];
        binom[0][0] = 1;
        for (int n = 1; n <= M; n++) {
            binom[n][0] = 1;
            for (int k = 1; k <= n; k++)
                binom[n][k] = binom[n-1][k-1] + binom[n-1][k];
        }

        double[][] prob = new double[N][M+1];
        double[] base = new double[N];
        for (int i = 0; i < N; i++) {
            base[i] = L / V[i];
            for (int k = 0; k <= M; k++)
                prob[i][k] = binom[M][k] * Math.pow(P[i], k) * Math.pow(1-P[i], M-k);
        }

        for (int i = 0; i < N; i++) {
            double winProb = 0;
            for (int k = 0; k <= M; k++) {
                double ti = base[i] + k * T[i];
                double p = prob[i][k];
                for (int j = 0; j < N; j++) {
                    if (j == i) continue;
                    double pj = 0;
                    for (int m = 0; m <= M; m++)
                        if (base[j] + m * T[j] > ti) pj += prob[j][m];
                    p *= pj;
                }
                winProb += p;
            }
            System.out.printf("%.6f%n", winProb);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != -1 && c != '.') {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c > ' ' && c != -1) {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int M = fs.nextInt();
        double L = fs.nextDouble();

        double[] p = new double[N];
        double[] q = new double[N];
        double[] t = new double[N];
        double[] base = new double[N];

        for (int i = 0; i < N; i++) {
            double P = fs.nextDouble();
            double T = fs.nextDouble();
            double V = fs.nextDouble();
            p[i] = P / 100.0;
            q[i] = 1.0 - p[i];
            t[i] = T;
            base[i] = L / V;
        }

        double[] ans = new double[N];

        // For runner i, total time = base[i] + k * t[i], where k ~ Binomial(M, p[i]).
        // Probability runner i wins:
        // sum_k Pr_i(k) * product_{j!=i} Pr(time_j > time_i(k))
        //
        // For each opponent j we need:
        //   Pr(base[j] + x*t[j] > target), x ~ Bin(M, p[j])
        // Since x is integer, this is:
        //   x > (target - base[j]) / t[j]
        // let need = floor((target - base[j]) / t[j]) + 1
        // then probability = sum_{x=max(need,0)}^M binomProb_j[x]
        //
        // Precompute binomial pmf and suffix sums for each runner.

        double[][] pmf = new double[N][M + 1];
        double[][] suf = new double[N][M + 2]; // suf[i][k] = sum_{x=k}^M pmf[i][x]

        for (int i = 0; i < N; i++) {
            if (p[i] == 0.0) {
                pmf[i][0] = 1.0;
            } else if (q[i] == 0.0) {
                pmf[i][M] = 1.0;
            } else {
                pmf[i][0] = Math.pow(q[i], M);
                for (int k = 0; k < M; k++) {
                    pmf[i][k + 1] = pmf[i][k] * (M - k) / (double) (k + 1) * (p[i] / q[i]);
                }
            }
            suf[i][M + 1] = 0.0;
            for (int k = M; k >= 0; k--) {
                suf[i][k] = suf[i][k + 1] + pmf[i][k];
            }
        }

        final double EPS = 1e-12;

        for (int i = 0; i < N; i++) {
            double win = 0.0;
            for (int k = 0; k <= M; k++) {
                double myProb = pmf[i][k];
                if (myProb == 0.0) continue;

                double target = base[i] + k * t[i];
                double prod = 1.0;

                for (int j = 0; j < N; j++) {
                    if (j == i) continue;

                    double greaterProb;
                    if (t[j] == 0.0) {
                        // Opponent time is constant base[j]
                        greaterProb = (base[j] > target + EPS) ? 1.0 : 0.0;
                    } else {
                        double x = (target - base[j]) / t[j];
                        int need;
                        if (x < -1.0) {
                            need = 0;
                        } else {
                            need = (int) Math.floor(x + EPS) + 1;
                        }

                        if (need <= 0) greaterProb = 1.0;
                        else if (need > M) greaterProb = 0.0;
                        else greaterProb = suf[j][need];
                    }

                    prod *= greaterProb;
                    if (prod == 0.0) break;
                }

                win += myProb * prod;
            }
            ans[i] = win;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            sb.append(String.format(Locale.US, "%.10f%n", ans[i]));
        }
        System.out.print(sb.toString());
    }
}
